#!/usr/bin/env node
/**
 * compare-temple.mjs — Phase-1 verification: Flash temple scene vs the
 * original UE5 hybrid sb3.
 *
 * Compares dist/temple.sb3 (generated by the TS engine) against the
 * original scratch-ue5-pen-research/sb3/ue5_lumen_hybrid.sb3:
 *   1. Counts: blocks, variables, lists, opcode histogram, proc list.
 *   2. Per-ID block comparison (IDs are deterministic in both builders;
 *      identical emission order => identical IDs).
 *   3. List initial values (the baked SoA scene data), deep-compared.
 *   4. Transpile comparison: distilled's tools/transpile.py is run on
 *      both sb3 files and the generated TS is diffed line-wise; also
 *      counts rt.unimplemented stubs (must be 0 on both sides).
 *
 * Full byte equality is NOT the phase-1 goal (design section 3.4):
 * the target is visual/behavioral equivalence. This tool reports the
 * numbers; exit code is 0 when there are no *structural* surprises
 * (missing blocks, stubbed opcodes, differing list data).
 *
 * Usage: node tools/compare-temple.mjs [--orig <path>] [--gen <path>]
 * Requires: python3, ~/workspace/TACT-AIM-distilled (transpile oracle).
 */
import { execFileSync } from 'node:child_process';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';
import { loadProject } from './validate.mjs';

const ROOT = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const args = process.argv.slice(2);
function argVal(flag, dflt) {
  const i = args.indexOf(flag);
  return i >= 0 ? args[i + 1] : dflt;
}
const ORIG = argVal('--orig', path.join(os.homedir(), 'workspace/scratch-ue5-pen-research/sb3/ue5_lumen_hybrid.sb3'));
const GEN = argVal('--gen', path.join(ROOT, 'dist', 'temple.sb3'));
const TRANSPILE_PY = path.join(os.homedir(), 'workspace/TACT-AIM-distilled/tools/transpile.py');
const DRIVER = path.join(ROOT, 'tools', 'transpile_driver.py');

function stats(pj) {
  const s = { targets: [], blocks: 0, vars: 0, lists: 0, opcodes: new Map(), procs: [] };
  for (const t of pj.targets) {
    const blocks = Object.values(t.blocks || {}).filter((b) => typeof b === 'object' && b !== null);
    s.blocks += blocks.length;
    s.vars += Object.keys(t.variables || {}).length;
    s.lists += Object.keys(t.lists || {}).length;
    for (const b of blocks) {
      s.opcodes.set(b.opcode, (s.opcodes.get(b.opcode) || 0) + 1);
      if (b.opcode === 'procedures_prototype') s.procs.push(b.mutation?.proccode);
    }
    s.targets.push(t.name);
  }
  return s;
}

function spriteOf(pj) {
  return pj.targets.find((t) => !t.isStage);
}

function compareBlocks(a, b) {
  const ba = spriteOf(a).blocks;
  const bb = spriteOf(b).blocks;
  let identical = 0;
  const differing = [];
  const ids = new Set([...Object.keys(ba), ...Object.keys(bb)]);
  for (const id of ids) {
    const x = ba[id];
    const y = bb[id];
    if (JSON.stringify(x) === JSON.stringify(y)) identical++;
    else differing.push({ id, a: x?.opcode, b: y?.opcode });
  }
  return { identical, differing };
}

function compareLists(a, b) {
  const la = spriteOf(a).lists;
  const lb = spriteOf(b).lists;
  let identical = 0;
  const differing = [];
  const names = new Set([...Object.keys(la), ...Object.keys(lb)]);
  for (const name of names) {
    const x = la[name]?.[1];
    const y = lb[name]?.[1];
    if (JSON.stringify(x) === JSON.stringify(y)) identical++;
    else differing.push(name);
  }
  return { identical, differing, total: names.size };
}

function compareVars(a, b) {
  const va = spriteOf(a).variables;
  const vb = spriteOf(b).variables;
  let identical = 0;
  const differing = [];
  const names = new Set([...Object.keys(va), ...Object.keys(vb)]);
  for (const name of names) {
    if (JSON.stringify(va[name]) === JSON.stringify(vb[name])) identical++;
    else differing.push(name);
  }
  return { identical, differing, total: names.size };
}

function transpile(sb3, outdir) {
  fs.rmSync(outdir, { recursive: true, force: true });
  fs.mkdirSync(outdir, { recursive: true });
  execFileSync('python3', [DRIVER, TRANSPILE_PY, sb3, outdir], { stdio: 'pipe' });
  const genDir = path.join(outdir, 'gen');
  const files = new Map();
  const walk = (d) => {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      const p = path.join(d, e.name);
      if (e.isDirectory()) walk(p);
      else files.set(path.relative(genDir, p), fs.readFileSync(p, 'utf-8'));
    }
  };
  walk(genDir);
  return files;
}

function lineDiff(a, b) {
  const la = a.split('\n');
  const lb = b.split('\n');
  let same = 0;
  const n = Math.max(la.length, lb.length);
  for (let i = 0; i < n; i++) if (la[i] === lb[i]) same++;
  return { total: n, same, differing: n - same };
}

const orig = loadProject(ORIG);
const gen = loadProject(GEN);
const so = stats(orig);
const sg = stats(gen);

console.log('=== Flash temple vs original UE5 hybrid ===');
console.log(`orig: ${ORIG}`);
console.log(`gen:  ${GEN}`);
console.log(`targets: orig=${so.targets.join(',')} gen=${sg.targets.join(',')}`);
console.log(`blocks:  orig=${so.blocks} gen=${sg.blocks} (diff ${sg.blocks - so.blocks})`);
console.log(`vars:    orig=${so.vars} gen=${sg.vars} (sprite+stage)`);
console.log(`lists:   orig=${so.lists} gen=${sg.lists}`);
console.log(`procs:   orig=${so.procs.length} gen=${sg.procs.length}`);
const procDiff = so.procs.filter((p) => !sg.procs.includes(p));
console.log(`procs missing in gen: ${procDiff.length ? procDiff.join(', ') : 'none'}`);

const opDiff = [];
for (const op of new Set([...so.opcodes.keys(), ...sg.opcodes.keys()])) {
  const d = (sg.opcodes.get(op) || 0) - (so.opcodes.get(op) || 0);
  if (d !== 0) opDiff.push(`${op}: ${d > 0 ? '+' : ''}${d}`);
}
console.log(`opcode histogram diffs: ${opDiff.length ? opDiff.join('; ') : 'none'}`);

const bc = compareBlocks(orig, gen);
console.log(`blocks per-ID identical: ${bc.identical}/${bc.identical + bc.differing.length}`);
for (const d of bc.differing.slice(0, 10)) console.log(`  diff ${d.id}: orig=${d.a} gen=${d.b}`);

const lc = compareLists(orig, gen);
console.log(`lists identical: ${lc.identical}/${lc.total}${lc.differing.length ? ' differing: ' + lc.differing.join(', ') : ''}`);
const vc = compareVars(orig, gen);
console.log(`variables identical: ${vc.identical}/${vc.total}${vc.differing.length ? ' differing: ' + vc.differing.slice(0, 10).join(', ') : ''}`);

console.log('=== transpile comparison (distilled oracle) ===');
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'flash-cmp-'));
const ta = transpile(ORIG, path.join(tmp, 'orig'));
const tb = transpile(GEN, path.join(tmp, 'gen'));
let stubA = 0, stubB = 0, totSame = 0, totLines = 0;
for (const [name, content] of ta) {
  stubA += (content.match(/rt\.unimplemented/g) || []).length;
  const other = tb.get(name);
  if (other === undefined) { console.log(`  file missing in gen: ${name}`); continue; }
  stubB += (other.match(/rt\.unimplemented/g) || []).length;
  const d = lineDiff(content, other);
  totSame += d.same; totLines += d.total;
  console.log(`  ${name}: ${content.split('\n').length} vs ${other.split('\n').length} lines, ${d.differing} differing`);
}
console.log(`transpile stubs: orig=${stubA} gen=${stubB}`);
console.log(`transpile lines identical: ${totSame}/${totLines}`);

const hardFail = bc.differing.some((d) => d.a === undefined || d.b === undefined)
  || lc.differing.length > 0 || stubB > 0 || procDiff.length > 0;
console.log(hardFail ? 'RESULT: structural surprises present (see above)' : 'RESULT: no structural surprises');
process.exit(hardFail ? 1 : 0);
